logger = logging.getLogger(__name__)

# enabled only when lanes >= _WIDE_LARGE_MIN_LANES - fixed 32768-lane large blocks +
# grid cap 256 + block stride loop; the threshold is 16*32768 to guarantee at least 16 programs,
# below which the element path is used (too few large-block programs degrades performance, and small sizes are
# launch-bound where the wide channel brings no benefit).
# Element path (medium sizes / 8-byte dtypes / unaligned / int64-domain fallback).
_WIDE_LARGE_MIN_LANES = 524288
_WIDE_BLOCK = 32768
_WIDE_GRID_CAP = 256
_WIDE_LARGE_WARPS = 8

# Small-size tier n <= _FLAT_SMALL_MAX_ELEMENTS reproduces the old single BLOCK=1024 launch
# (official bench measures 3.04-3.27us stably here; a BLOCK of 16384 wastes ~1us on masked
# 16384-lane idle work at n=512. detach_copy once measured the opposite on 1B dtypes -
# a fixed large block beat a snug small block; that conclusion does not transfer across itemsize/process state).
# Large BLOCK is used only for medium sizes and above.
# For n <= 2^31 - 2^15, (cdiv(n, BLOCK)-1)*BLOCK + BLOCK-1 still fits int32;
_FLAT_BLOCK = 16384
_FLAT_GRID_CAP = 256
_FLAT_WARPS = 8
_FLAT_SMALL_BLOCK = 1024
_FLAT_SMALL_MAX_ELEMENTS = 16384
_FLAT_SMALL_WARPS = 4
# above that switch to the int64 offset arm (at n = 2^31-1 int32 cdiv truncates the block count,
# which the detach_copy probe measured as silently wrong values).
# The int32 offset safe range of the wide channel is guarded by total bytes: with bytes <= 2^31-1
