# The external /opt/triton_gcu converter occasionally SIGSEGVs on cold compilation (compiler_problems/P02),
# #
_TOOLCHAIN_COMPILE_RETRIES = 3


@triton.jit
def _nvj_copy_wide_kernel(
    src_lanes_ptr,
    dst_lanes_ptr,
    num_lanes,
    chunks_per_program,
    BLOCK_X: tl.constexpr,
    MASKED: tl.constexpr,
):
    """Wide-channel path: int64 view moves whole 8-byte lanes.

    Input and output are both reinterpreted with ``view(torch.int64)``, each lane moving 8 bytes,
    reducing per-element address arithmetic and memory requests to 1/2 (fp32) or 1/4 (fp16/bf16).
    The host already guards int32 overflow by total bytes, so all indices remain int32.
    When ``MASKED == False`` (exact division and a single chunk), the tail-block mask is specialized away.
    """
    pid = tl.program_id(axis=0)
    num_programs = tl.num_programs(axis=0)
    for chunk_index in range(chunks_per_program):
        block_index = pid + chunk_index * num_programs
        offsets = block_index * BLOCK_X + tl.arange(0, BLOCK_X)
        if MASKED:
            active = offsets < num_lanes
            tl.store(
                dst_lanes_ptr + offsets,
                tl.load(src_lanes_ptr + offsets, mask=active),
                mask=active,
            )
        else:
            tl.store(dst_lanes_ptr + offsets, tl.load(src_lanes_ptr + offsets))


@triton.jit
def _nvj_copy_flat_kernel(
    src_ptr,
    dst_ptr,
    n_elements,
    chunks_per_program,
    BLOCK_X: tl.constexpr,
    IDX64: tl.constexpr,
):
    """Element path: grid-stride elementwise transfer, the main path for small/medium sizes and non-wide dtypes.

    With ``IDX64 == True`` the offset chain is explicitly widened to int64, covering huge buffers whose element
    count leaves the int32 safe range (correctness arm, outside the benchmark scope).
    """
    pid = tl.program_id(axis=0)
    num_programs = tl.num_programs(axis=0)
    for chunk_index in range(chunks_per_program):
        block_index = pid + chunk_index * num_programs
        if IDX64:
            offsets = block_index.to(tl.int64) * BLOCK_X + tl.arange(0, BLOCK_X).to(
                tl.int64
            )
        else:
            offsets = block_index * BLOCK_X + tl.arange(0, BLOCK_X)
        active = offsets < n_elements
        tl.store(
            dst_ptr + offsets, tl.load(src_ptr + offsets, mask=active), mask=active
        )


def _launch_with_toolchain_retry(kernel, grid, args, launch_kwargs):
    """P02: retry the launch on an occasional cold-compile SIGSEGV; deterministic failures are re-raised unchanged
    after retries are exhausted."""
    for attempt in range(_TOOLCHAIN_COMPILE_RETRIES):
        try:
            return kernel[grid](*args, **launch_kwargs)
        except Exception as error:
            if attempt == _TOOLCHAIN_COMPILE_RETRIES - 1:
                raise
            logger.debug(
                "_nested_view_from_jagged_copy: retrying Triton launch after "
                "toolchain failure (attempt %d): %r",
                attempt,
                error,
            )


